INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Add your name and mobile number to rate this recipe. Your number is never shown.', 'hi', 'इस रेसिपी को रेट करने के लिए अपना नाम और मोबाइल नंबर जोड़ें। आपका नंबर कभी नहीं दिखाया जाता।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Add your name and mobile number to rate this recipe. Your number is never shown.', 'bn', 'এই রেসিপি রেট করতে আপনার নাম ও মোবাইল নম্বর দিন। আপনার নম্বর কখনও দেখানো হয় না।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Add your name and mobile number to rate this recipe. Your number is never shown.', 'gu', 'આ રેસીપીને રેટ કરવા તમારું નામ અને મોબાઇલ નંબર ઉમેરો. તમારો નંબર ક્યારેય બતાવાતો નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Add your name and mobile number to send a remark. Only your name is shown, never your number.', 'hi', 'टिप्पणी भेजने के लिए अपना नाम और मोबाइल नंबर जोड़ें। सिर्फ़ आपका नाम दिखता है, नंबर कभी नहीं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
